let dockEpoch=performance.now();
let warehouseObserver;
const state={page:'overview',truck:0,rack:2,parcel:1};
const trucks=['TRK-2048','TRK-2051','TRK-2043','TRK-2072'];const racks=['A-03','A-04','B-01','B-02'];const parcels=['BX-8472','BX-8473','BX-8434','BX-8745',...Array.from({length:14},(_,i)=>`BX-${8476+i}`)];
const asset=(type,cls='')=>`<div class="asset ${type} ${cls}" role="img" aria-label="${{truck:'白色物流卡车与蓝色集装箱',rack:'蓝色智能货架',parcel:'蓝色封箱带货箱',conveyor:'物流分拣传送带'}[type]}"></div>`;
const panel=(title,body,extra='')=>`<section class="panel"><div class="panel-title">${title}${extra}</div>${body}</section>`;
const stat=(label,value,unit='')=>`<div class="stat"><small>${label}</small><b>${value}</b><em>${unit}</em></div>`;
const title=(label,id,meta,status)=>`<div class="page-heading"><div><div class="eyebrow">— 物流数字孪生 / ${label}</div><h1>${label} <span>${id}</span></h1><div>${meta}</div></div><div class="status"><span><i class="dot"></i>${status}</span><span>最近更新 <span id="updated">10:32:45</span></span></div></div>`;
function selectors(type,items,index){return `<div class="selectors">${items.map((n,i)=>`<button class="select-card ${index===i?'selected':''}" data-select="${type}" data-index="${i}" aria-pressed="${index===i}"><div><b>${type==='rack'?'货架 ':''}${n}</b><small>${type==='truck'?['上海 → 杭州 · 运输中','苏州 → 上海 · 卸货中','上海 → 宁波 · 装载中','上海 → 杭州 · 运输中'][i]:type==='rack'?'库位利用率 100% · 运行中':'电子配件 · 24 件'}</small></div><div class="thumb">${asset(type)}</div></button>`).join('')}</div>`}
function stage(type,label,detail='点击设备查看关联货箱'){if(type==='truck')return truckStage(label);return `<div class="stage"><div class="stage-caption">${label}</div><div class="stage-detail">${detail}</div><button class="equipment-driver ${type==='truck'?'truck-driver':''}" data-action="inspect" style="width:100%;height:100%;padding:0" aria-label="查看货箱详情">${asset(type)}</button><div class="stage-legend"><span><i class="dot"></i>实时数字孪生</span><span>自动同步中</span><span>视图 · 正视图</span></div></div>`}
function truckStage(label){return `<div class="stage cargo-stage"><div class="stage-caption">${label}</div><div class="stage-detail">${[18,12,15,18][state.truck]} 个包裹 / 点击箱体查看详情</div><div class="equipment-driver truck-driver truck-visual">${asset('truck')}<svg class="cargo-overlay" viewBox="0 0 1699 926" aria-label="车厢包裹分布">${Array.from({length:18},(_,i)=>{const col=i%6,row=Math.floor(i/6);return `<foreignObject x="${458+col*173}" y="${300+row*113}" width="153" height="96"><button xmlns="http://www.w3.org/1999/xhtml" class="cargo-button ${i>=[18,12,15,18][state.truck]?'cargo-empty':''}" ${i>=[18,12,15,18][state.truck]?'disabled':''} data-parcel="${i}" aria-label="查看包裹 ${parcels[i]}"><span>${i>=[18,12,15,18][state.truck]?'空库位':parcels[i]}</span><small>${i>=[18,12,15,18][state.truck]?'等待装载':`${[24,12,9][i%3]} 件 · 已装车`}</small><em>↗</em></button></foreignObject>`}).join('')}</svg></div><div class="stage-legend"><span><i class="dot"></i>包裹已装载 ${[18,12,15,18][state.truck]} / 18</span><span>蓝色箱体可点击</span></div></div>`}
function dockTraffic(){return `<div class="dock-traffic" aria-label="右侧装卸区车辆进出动画">${[0,1,2].map(i=>`<div class="dock-lane dock-lane-${i}" style="--phase:-${i*8}s"><div class="dock-vehicle"><img src="assets/dock-truck.png" alt="装卸区运输卡车" draggable="false"/><span class="dock-vehicle-label"><i></i>${trucks[i]}<small data-dock-status="${i}">入库停靠</small></span></div></div>`).join('')}</div>`}
function fleetBoard(){return panel('车辆进出动态',`<div class="fleet-totals"><div><small>今日出车</small><b>18<em> 辆</em></b></div><div><small>今日入车</small><b>12<em> 辆</em></b></div><div><small>待发车辆</small><b>03<em> 辆</em></b></div></div><div class="fleet-events"><button data-vehicle="0"><span class="fleet-direction out">出车</span><span><b>沪A · 8F62K</b><small>上海 → 杭州 · 18 箱已装载</small></span><time>14:32<small>已出园</small></time></button><button data-vehicle="1"><span class="fleet-direction in">入车</span><span><b>沪A · 7D31M</b><small>苏州 → 上海 · 12 箱待卸货</small></span><time>14:28<small>卸货中</small></time></button><button data-vehicle="2"><span class="fleet-direction out">出车</span><span><b>沪A · 5C28N</b><small>上海 → 宁波 · 15 箱装载中</small></span><time>15:00<small>计划发车</small></time></button></div>`,'<span class="green">园区闸口在线</span>')}
function rows(type){return `<table><thead><tr>${(type==='rack'?['库位','货箱编号','货品名称','数量','入库时间','状态','']:['货箱编号','货品名称','所在库位','重量','状态','']).map(v=>`<th>${v}</th>`).join('')}</tr></thead><tbody>${[0,1,2].map((i)=>`<tr>${(type==='rack'?[`${racks[state.rack]}-0${i+1}`,parcels[i],['精密电子配件','工业传感器','智能控制模组'][i],`${[24,12,9][i]} 件`,'今日 10:46','<span class="green">已入库</span>']:[parcels[i],['精密电子配件','工业传感器','智能控制模组'][i],`集装箱 0${i+1}`,`${[18.8,23.4,16.5][i]} kg`,'<span class="green">已装车</span>']).map(v=>`<td>${v}</td>`).join('')}<td><button data-parcel="${i}">查看 ↗</button></td></tr>`).join('')}</tbody></table>`}
function truckPage(){return `${title('运输卡车',trucks[state.truck],`车辆管理 / ${['上海 → 杭州','苏州 → 上海','上海 → 宁波','上海 → 杭州'][state.truck]} / 数字孪生实时监控`,['运输正常','入园卸货中','装载作业中','运输正常'][state.truck])}<div class="hero-layout">${stage('truck','TRUCK VIEW / 车辆视图')}${panel('车辆概况',`<div class="plate">沪A · ${['8F62K','7D31M','5C28N','9H16P'][state.truck]}</div><div class="muted">厢式重型货车 / 王师傅</div><div class="bar-label"><span>装载进度</span><b>${[100,67,83,100][state.truck]}%</b></div><div class="segments">${'<i></i>'.repeat(10)}</div><div class="stats-grid">${stat('已装货箱',[18,12,15,18][state.truck],'箱')}${stat('空余库位',[0,6,3,0][state.truck],'个')}${stat('载重','7.34','吨')}${stat('运输时长','03','天')}</div><div class="route"><b>运输路线</b><div class="route-line"><span>${state.truck===1?'苏州 · 分拨中心':'上海 · 分拨中心'}</span><span>● ${['杭州','上海','宁波','杭州'][state.truck]} · 转运站</span></div><div class="muted">预计今日 16:30 到达 · 全程 182 km</div></div>`,`<span class="green">${['运输中','卸货中','装载中','运输中'][state.truck]}</span>`)}</div>${selectors('truck',trucks,state.truck)}<div class="bottom-grid">${panel('装载清单',rows('truck'),`<span class="title-extra">共 ${[18,12,15,18][state.truck]} 箱 · 展示前 3 箱</span>`)}${panel('任务进度',`<div class="tracking">${['仓库拣货','货物装车','运输途中','签收交付'].map((v,i)=>`<div class="step"><span class="check">${i<3?'✓':'4'}</span><b>${v}</b><small>${['09:20','10:15','进行中','待完成'][i]}</small></div>`).join('')}</div>`,'<span class="title-extra">单号 SO-20261102-001</span>')}</div>`}
function rackPage(){return `${title('智能货架',racks[state.rack],'库区 B / 智能仓储 / 3 层 × 4 列 / 载重 6 吨','正常运行')}<div class="hero-layout">${stage('rack','RACK ELEVATION / 货架立面')}${panel('货架状态',`<div><b class="big-number">100.0</b><span class="muted"> % 库位使用率</span></div><div class="progress"><i></i></div><div class="stats-grid">${stat('总库位','12','个')}${stat('占用库位','12','个')}${stat('货箱数量','44','箱')}${stat('货品种类','9','类')}</div><div class="note"><b>温湿度正常 · 48 个传感器</b><br><span class="muted">所有库位状态已同步，暂无异常告警。<br>温度 22°C / 相对湿度 46%</span></div>`,`<span class="green">正常</span>`)}</div>${selectors('rack',racks,state.rack)}<div class="bottom-grid">${panel('库位详情',rows('rack'),'<span class="title-extra">展示部分 · 含交叉关联</span>')}${panel('货品分布',`<div class="distribution">${['精密电子配件','工业传感器','智能控制模组'].map((n,i)=>`<div><span>${n}</span><b>${[33,34,33][i]}%</b><div class="progress"><i style="width:${[66,68,66][i]}%"></i></div></div>`).join('')}</div>`)}</div>`}
function parcelPage(){return `${title('货箱详情',parcels[state.parcel],'精密电子配件 / 数字货物追踪 / RFID · 在线','待出库')}<div class="parcel-layout"><div class="parcel-left">${stage('parcel','PARCEL VIEW / 货箱视图','独立货箱数字档案')}${selectors('parcel',parcels.slice(0,4),state.parcel)}</div><div class="parcel-right"><div class="metrics">${[['箱内件数','24','件'],['货箱重量','17.2','kg'],['货箱体积','0.108','m³']].map(a=>`<section class="panel"><span class="muted">${a[0]}</span><b>${a[1]}<em> ${a[2]}</em></b><span class="muted">传感器实时同步</span></section>`).join('')}</div>${panel('货箱档案',`<div class="details">${[['货品名称','精密电子配件'],['货品编号','EL-4308 / 24 件'],['关联订单','SO-20261102-001'],['货箱尺寸','60 × 40 × 45 cm'],['净重 / 毛重','17.2 / 18.8 kg'],['目标库位',`${racks[state.rack]}-04`]].map(a=>`<div><span>${a[0]}</span><b>${a[1]}</b></div>`).join('')}</div><div class="muted" style="margin-top:25px">标签　 RFID　　易碎品　　向上放置</div>`,'<span class="green">档案完整</span>')}<div class="parcel-lower">${panel('流转轨迹',`<ul class="timeline"><li><b>上架至 ${racks[state.rack]}-04</b><small>今日 10:46:32 · 自动入库</small></li><li><b>完成入库质检</b><small>今日 10:38:15 · 质检合格</small></li><li><b>到达华东集散中心</b><small>今日 09:20:08 · 已收货</small></li></ul>`,'<span class="title-extra">流转记录</span>')}<div>${panel('包装与载重',`<span class="muted">包装完好度 <b style="float:right;color:#566f81">100%</b></span><div class="progress"><i></i></div><div class="details"><div><span>封箱状态</span><b>封签完好</b></div><div><span>存放要求</span><b>干燥避光</b></div></div>`)}${panel('关联业务对象',`<button class="link-card" data-page="rack"><span>▤　所属货架 ${racks[state.rack]}-04</span><span>↗</span></button><button class="link-card" data-page="truck"><span>▰　运输车辆 ${trucks[state.truck]}</span><span>↗</span></button>`)}</div></div></div></div>`}
function overviewPage(){return `<div class="overview-scene"><div class="warehouse-world"><div class="warehouse-canvas"><div class="warehouse-render"></div><div class="scene-route route-one"></div><div class="scene-route route-two"></div><svg class="conveyor-motion" viewBox="0 0 1672 941" aria-hidden="true"><path class="conveyor-guide" d="M 860 552 L 1000 634 L 1140 714 L 1300 808 L 1460 902"/>${[0,1,2].map(i=>`<g><animateMotion dur="14s" begin="-${i*14/3}s" repeatCount="indefinite" calcMode="paced" path="M 860 552 L 1000 634 L 1140 714 L 1300 808 L 1460 902"/><ellipse cx="0" cy="1" rx="12" ry="4" fill="#526c8426"/><polygon points="-11,-18 0,-24 13,-17 2,-11" fill="#f2d6af"/><polygon points="-11,-18 2,-11 2,1 -11,-6" fill="#d5ac7e"/><polygon points="2,-11 13,-17 13,-5 2,1" fill="#bb956a"/><path d="M -6 -21 L 7 -14 L 7 -2" fill="none" stroke="#63a9dc" stroke-width="3"/></g>`).join('')}</svg>${dockTraffic()}<div class="dock-signal"></div></div></div><div class="overview-heading"><div class="eyebrow">SMART LOGISTICS / 智慧物流中心</div><h1>让每一件货物的流转清晰可见</h1><p>仓储、分拣与运输 · 全链路实时协同</p></div><aside class="overview-rail">${panel('今日作业概览',`<span class="muted">今日流转货物</span><div class="overview-number"><b data-count="13023">13,023</b><em>件</em></div><div class="trend-label"><span>较昨日同期</span><span class="green">↗ 12.8%</span></div><svg class="sparkline" viewBox="0 0 250 62" aria-label="今日流转趋势"><defs><linearGradient id="chartFade" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#5cacec" stop-opacity=".19"/><stop offset="1" stop-color="#5cacec" stop-opacity="0"/></linearGradient></defs><path d="M0 45 Q20 43 30 31 T62 30 T94 37 T125 29 T156 25 T187 33 T217 19 T250 13 L250 62 L0 62Z" fill="url(#chartFade)"/><path class="trend-line" d="M0 45 Q20 43 30 31 T62 30 T94 37 T125 29 T156 25 T187 33 T217 19 T250 13" fill="none" stroke="#5194bb" stroke-width="1.7"/></svg><div class="axis-labels"><span>06:00</span><span>12:00</span><span>18:00</span></div>`,'<span class="title-extra">实时更新</span>')}${panel('运营指标',`<div class="operation-metrics">${[['库位利用率','96.8','%'],['在库货箱','8,476','箱'],['运输车辆','18','辆'],['运行设备','03','组']].map(a=>`<div><span>${a[0]}</span><b>${a[1]}<em>${a[2]}</em></b></div>`).join('')}</div>`,'<span class="green">今日</span>')}</aside><aside class="fleet-board">${fleetBoard()}</aside><div class="scene-hotspots"><button class="hotspot hotspot-rack" data-page="rack"><i></i><span><small>WAREHOUSE / B-01</small><b>智能货架 <em>↗</em></b></span></button><button class="hotspot hotspot-truck" data-page="truck"><i></i><span><small>TRANSPORT / TRK-2048</small><b>运输卡车 <em>↗</em></b></span></button><button class="hotspot hotspot-conveyor" data-page="conveyor"><i></i><span><small>SORTING / CV-001</small><b>传送带设备 <em>↗</em></b></span></button><button class="hotspot hotspot-parcel" data-page="parcel"><i></i><span><small>PARCEL / BX-8473</small><b>货物追踪 <em>↗</em></b></span></button></div><div class="scene-live"><i class="dot"></i>物流中心实时视图 <span>自动巡航中</span></div></div><div class="overview-bottom">${panel('设备运行效率',`<div class="efficiency"><b>98.2<em>%</em></b><span class="green">运行平稳</span></div><div class="progress"><i style="width:98.2%"></i></div><span class="muted">设备综合运行效率 / 今日</span><button class="text-link" data-page="conveyor">查看设备详情 ↗</button>`)}${panel('今日货物流转',`<div class="volume-head"><b data-count="2360">2,360</b><span class="muted"> 件 / 已完成分拣</span></div><div class="volume-chart">${[32,48,59,75,64,55,82,68].map((v,i)=>`<div><div class="bar-pair"><i style="--height:${v}%;--delay:${i*70}ms"></i><i style="--height:${v*.8}%;--delay:${i*70+60}ms"></i></div><small>${String(i*2+6).padStart(2,'0')}:00</small></div>`).join('')}</div>`,'<span class="title-extra">入库 / 出库</span>')}${panel('待办动态',`<div class="live-feed"><button data-page="truck"><i class="feed-dot"></i><span><b>TRK-2048 即将到达集散中心</b><small>运输任务 · 预计 16:30 到达</small></span><em>↗</em></button><button data-page="conveyor"><i class="feed-dot mint"></i><span><b>AGV 07 完成货箱转运</b><small>智能分拣 · 2 分钟前</small></span><em>↗</em></button><button data-page="rack"><i class="feed-dot"></i><span><b>库区 B-01 入库任务已完成</b><small>仓储作业 · 5 分钟前</small></span><em>↗</em></button></div>`,'<span class="green">全部正常</span>')}</div>`}
function conveyorPage(){return `${title('智能分拣','CV-001','分拣作业区 / 自动输送系统 / A 号线','正常运行')}<div class="hero-layout">${stage('conveyor','CONVEYOR VIEW / 输送设备')}${panel('设备状态',`<div class="big-number">99.8<span class="muted"> %</span></div><div class="muted">分拣准确率</div><div class="progress"><i></i></div><div class="stats-grid">${stat('今日分拣','2,486','件')}${stat('处理速度','1,280','件/h')}${stat('皮带速度','1.2','m/s')}${stat('异常货箱','0','件')}</div><button class="link-card" data-action="pause"><span id="pause-label">暂停输送演示</span><span>Ⅱ</span></button>`,'<span class="green">运行中</span>')}</div><div class="bottom-grid" style="margin-top:20px">${panel('分拣货箱',rows('truck'))}${panel('运行记录',`<div class="note">10:46:32　货箱 BX-8473 分拣完成<br>10:45:18　货箱 BX-8472 进入输送线<br>10:42:05　设备自检通过，开始运行</div>`)}</div>`}
function render(){dockEpoch=performance.now();document.body.dataset.page=state.page;document.querySelector('#app').innerHTML=`<header><button class="brand" data-page="overview" aria-label="返回运营总览"><span class="mark"><i></i><i></i><i></i></span><span><b>蓝枢 · 智慧物流</b><small>LANSHU · LOGISTICS TWIN</small></span></button><nav aria-label="主导航">${[['overview','运营总览'],['truck','运输车辆'],['rack','仓储管理'],['parcel','货物追踪']].map(a=>`<button class="${state.page===a[0]?'active':''}" data-page="${a[0]}">${a[1]}</button>`).join('')}</nav><div class="header-end"><span><i class="dot"></i>系统在线 / 数据同步</span><time id="clock"></time><button class="icon-button" data-action="fullscreen" aria-label="切换全屏">⛶</button></div></header><main>${({truck:truckPage,rack:rackPage,parcel:parcelPage,overview:overviewPage,conveyor:conveyorPage}[state.page])()}</main><footer><span>蓝枢 · 智慧物流　智慧物流数字孪生平台</span><span>演示数据 · 设备状态模拟展示 / 所有设备状态正常</span></footer>`;clock();animateMetrics();fitWarehouse();syncDockTraffic();}
function clock(){const now=new Date();const el=document.querySelector('#clock');if(el)el.textContent=now.toLocaleString('zh-CN',{hour12:false});const up=document.querySelector('#updated');if(up)up.textContent=now.toLocaleTimeString('zh-CN',{hour12:false})}setInterval(clock,1000);
function toast(msg){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=msg;document.body.append(el);setTimeout(()=>el.remove(),2500)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.vehicle!==undefined){state.truck=Number(b.dataset.vehicle);state.page='truck';render()}if(b.dataset.page){state.page=b.dataset.page;render()}if(b.dataset.select){state[b.dataset.select]=Number(b.dataset.index);render()}if(b.dataset.parcel!==undefined){state.parcel=Number(b.dataset.parcel);state.page='parcel';render()}if(b.dataset.action==='inspect'){state.page='parcel';render()}if(b.dataset.action==='fullscreen'){if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen().catch(()=>toast('请使用浏览器全屏功能'))}if(b.dataset.action==='pause'){const l=document.querySelector('#pause-label');l.textContent=l.textContent.includes('暂停')?'恢复输送演示':'暂停输送演示';document.querySelector('.stage .asset').style.animationPlayState=l.textContent.includes('恢复')?'paused':'running';toast(l.textContent.includes('恢复')?'输送演示已暂停':'输送演示已恢复')}});render();

function animateMetrics(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const start=performance.now();const nodes=[...document.querySelectorAll('[data-count]')];function frame(now){const p=Math.min((now-start)/1100,1);for(const node of nodes){const value=Number(node.dataset.count);node.textContent=Math.round(value*(1-Math.pow(1-p,3))).toLocaleString('en-US')}if(p<1)requestAnimationFrame(frame)}requestAnimationFrame(frame)}
let pointerFrame;document.addEventListener('pointermove',event=>{if(pointerFrame)return;pointerFrame=requestAnimationFrame(()=>{pointerFrame=null;const x=event.clientX/innerWidth-.5,y=event.clientY/innerHeight-.5;document.documentElement.style.setProperty('--pointer-x',`${x*10}px`);document.documentElement.style.setProperty('--pointer-y',`${y*7}px`)})});

function fitWarehouse(){warehouseObserver?.disconnect();const world=document.querySelector('.warehouse-world');const canvas=document.querySelector('.warehouse-canvas');if(!world||!canvas)return;warehouseObserver=new ResizeObserver(entries=>{const {width,height}=entries[0].contentRect;const scale=Math.max(width/1672,height/941);canvas.style.transform=`translate(${(width-1672*scale)/2}px,${(height-941*scale)*.48}px) scale(${scale})`});warehouseObserver.observe(world)}

function syncDockTraffic(){if(state.page!=='overview')return;const age=(performance.now()-(typeof dockEpoch==='undefined'?0:dockEpoch))/1000;for(let i=0;i<3;i++){const p=((age+i*8)%24)/24;const text=p<.3?'倒车入库':p<.55?'装卸停靠':'出车离库';const el=document.querySelector(`[data-dock-status="${i}"]`);if(el)el.textContent=text;const entry=document.querySelector(`.fleet-events [data-vehicle="${i}"] time small`);if(entry)entry.textContent=text;const badge=document.querySelector(`.fleet-events [data-vehicle="${i}"] .fleet-direction`);if(badge){badge.textContent=p<.3?'入车':p<.55?'停靠':'出车';badge.className='fleet-direction '+(p<.55?'in':'out')}}}setInterval(syncDockTraffic,500);
